/** @param {{ name: keyof typeof PATHS | keyof typeof NAV_ICONS, className?: string, strokeWidth?: number }} props */
/** Arrows and chevrons are drawn for the Arabic (RTL) layout and mirrored in English. */
const DIRECTIONAL = new Set(['arrow-left', 'arrow-right', 'chevron-left', 'chevron-right']);

export function Icon({ name, className = 'size-5', strokeWidth = 1.5, ...props }) {
    if (!isRtl && DIRECTIONAL.has(name)) {
        className = `${className} -scale-x-100`;
    }

    return (
        <svg
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            strokeWidth={strokeWidth}
            strokeLinecap="round"
            strokeLinejoin="round"
            className={className}
            aria-hidden="true"
            {...props}
        >
            {PATHS[name] ?? NAV_ICONS[name] ?? PATHS.info}
        </svg>
    );
}
